dci.instanceFilter:
function isYes(value)
{
   return (value != null) and (value.toUpperCase() in ["TRUE", "YES", "1"]);
}

interface = FindObject($1);
if (interface == null) return false;

if (isYes($node.getCustomAttribute("Template.InterfaceTraffic.Marked")))
{
   if (!isYes(interface.getCustomAttribute("Template.InterfaceTraffic"))) return false;
}
else
{
   if (interface.isLoopback or interface.name == "lo") return false;
   if (!(interface.ifType in [6, 7, 22])) return false; // ethernetCsmacd, iso88023Csmacd, propPointToPointSerial
   if (interface.expectedState != InterfaceExpectedState::UP) return false;

   attr = interface.getCustomAttribute("Template.InterfaceTraffic");
   if ((attr != null) and (attr.toUpperCase() in ["FALSE", "NO", "0"])) return false;

   attr = $node.getCustomAttribute("Template.InterfaceTraffic.Exclude");
   if ((attr != null) and (interface.ifName in attr.split(",", true))) return false;
}

return [interface.ifIndex, interface.ifName, interface];

