return [interface.ifIndex, interface.ifName, interface];

template.filter:
function isYes(value)
{
   return (value != null) and (value.toUpperCase() in ["TRUE", "YES", "1"]);
}

if (classof($object) != "Node") return false;
if (!isYes($object.getCustomAttribute("Template.InterfaceTraffic")) and !isYes($object.getCustomAttribute("Template.InterfaceTraffic.Marked"))) return false;
return $node.isAgent and !$node.hasAgentIfXCounters;

